// 获取青龙系统北京时间
function getQinglongTime() {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    const hours = String(now.getHours()).padStart(2, '0');
    const minutes = String(now.getMinutes()).padStart(2, '0');
    const seconds = String(now.getSeconds()).padStart(2, '0');
    return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
}

// 获取网络北京时间
async function getNetworkBeijingTime() {
    return new Promise((resolve) => {
        const options = {
            hostname: 'timeapi.io',
            path: '/api/Time/current/zone?timeZone=Asia/Shanghai',
            method: 'GET',
            timeout: 3000
        };
        const req = http.request(options, (res) => {
            let data = '';
            res.on('data', (chunk) => data += chunk);
            res.on('end', () => {
                try {
                    const timeData = JSON.parse(data);
                    const dateTime = timeData.dateTime;
                    resolve(dateTime.replace('T', ' ').split('.')[0]);
                } catch (error) {
                    resolve(getQinglongTime());
                }
            });
        });
        req.on('error', () => resolve(getQinglongTime()));
        req.on('timeout', () => {
            req.destroy();
            resolve(getQinglongTime());
        });
        req.end();
    });
}

// 获取当前北京时间（优先网络，失败使用青龙系统）
async function getCurrentBeijingTime() {
    try {
        return await getNetworkBeijingTime();
    } catch (error) {
        return getQinglongTime();
    }
}

// 解密主密钥
function decryptMasterData() {
    try {
        const masterDataKey = CryptoJS.MD5(
            "落花无情" + 
            "2662399823" + 
            "ks-luohua5.js" + 
            "MASTER_KEY_ENCRYPT"
        ).toString();
        
        // 验证密钥哈希
        const expectedHash = CryptoJS.MD5(masterDataKey).toString();
        if (expectedHash !== ENCRYPTED_MASTER_DATA.keyHash) {
            throw new Error('主密钥验证失败');
        }
        
        const decryptedMasterData = CryptoJS.AES.decrypt(
            ENCRYPTED_MASTER_DATA.ciphertext,
            masterDataKey,
            {
                iv: CryptoJS.enc.Hex.parse(ENCRYPTED_MASTER_DATA.iv),
                mode: CryptoJS.mode.CBC,
                padding: CryptoJS.pad.Pkcs7
            }
        );
        const masterDataStr = decryptedMasterData.toString(CryptoJS.enc.Utf8);
        if (!masterDataStr) {
            throw new Error('主密钥解密失败');
        }
        return JSON.parse(masterDataStr);
    } catch (error) {
        throw new Error('主密钥解密失败: ' + error.message);
    }
}

// 验证多个授权密钥
function verifyAuthKeys() {
    const authKey = process.env.AUTH_KEY;
    if (!authKey) {
        return { valid: false, reason: '未设置授权密钥' };
    }
    try {
        const authDataKey = CryptoJS.MD5("落花无情" + "2662399823" + "MULTI_AUTH_KEYS").toString();
        const decryptedAuthData = CryptoJS.AES.decrypt(
            ENCRYPTED_AUTH_DATA.ciphertext,
            authDataKey,
            {
                iv: CryptoJS.enc.Hex.parse(ENCRYPTED_AUTH_DATA.iv),
                mode: CryptoJS.mode.CBC,
                padding: CryptoJS.pad.Pkcs7
            }
        );
        const authDataStr = decryptedAuthData.toString(CryptoJS.enc.Utf8);
        if (!authDataStr) {
            return { valid: false, reason: '授权密钥验证失败' };
        }
        const authData = JSON.parse(authDataStr);
        
        // 检查输入的密钥是否在授权密钥列表中
        const isValid = authData.authKeys && authData.authKeys.includes(authKey);
        if (!isValid) {
            return { valid: false, reason: '授权密钥无效', totalKeys: authData.totalKeys };
        }
        
        return { 
            valid: true, 
            author: authData.author,
            authorQQ: authData.authorQQ,
            originalFile: authData.originalFile,
            keyIndex: authData.authKeys.indexOf(authKey) + 1,
            totalKeys: authData.totalKeys
        };
    } catch (error) {
        return { valid: false, reason: '授权密钥验证异常: ' + error.message };
    }
}

// 计算剩余时间
async function calculateRemainingTime(expireTime) {
    const currentTimeStr = await getCurrentBeijingTime();
    const now = new Date(currentTimeStr);
    const expire = new Date(expireTime);
    const remainingMs = expire - now;
    
    if (remainingMs <= 0) {
        return { 
            expired: true, 
            remaining: 0,
            days: 0, hours: 0, minutes: 0, seconds: 0,
            formatted: "0天0小时0分钟0秒"
        };
    }
    
    const remainingDays = Math.floor(remainingMs / (24 * 60 * 60 * 1000));
    const remainingHours = Math.floor((remainingMs % (24 * 60 * 60 * 1000)) / (60 * 60 * 1000));
    const remainingMinutes = Math.floor((remainingMs % (60 * 60 * 1000)) / (60 * 1000));
    const remainingSeconds = Math.floor((remainingMs % (60 * 1000)) / 1000);
    
    return {
        expired: false,
        remaining: remainingMs,
        days: remainingDays,
        hours: remainingHours,
        minutes: remainingMinutes,
        seconds: remainingSeconds,
        formatted: `${remainingDays}天${remainingHours}小时${remainingMinutes}分钟${remainingSeconds}秒`
    };
}

// 格式化时间为24小时制
function formatTime(date) {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    const hours = String(date.getHours()).padStart(2, '0');
    const minutes = String(date.getMinutes()).padStart(2, '0');
    const seconds = String(date.getSeconds()).padStart(2, '0');
    return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
}

async function checkKeyValidity(userKeyData, userKey) {
    const currentTimeStr = await getCurrentBeijingTime();
    const now = new Date(currentTimeStr);
    const createTime = new Date(userKeyData.createTime);
    const expireTime = new Date(userKeyData.expireTime);
    
    if (now > expireTime) {
        return { 
            valid: false, 
            reason: '密钥已到期',
            createTime: formatTime(createTime),
            expireTime: formatTime(expireTime),
            currentTime: currentTimeStr
        };
    }
    
    if (now < createTime) {
        return { 
            valid: false, 
            reason: '密钥尚未生效',
            createTime: formatTime(createTime),
            expireTime: formatTime(expireTime),
            currentTime: currentTimeStr
        };
    }
    
    const remainingTime = await calculateRemainingTime(userKeyData.expireTime);
    
    return { 
        valid: true, 
        createTime: formatTime(createTime),
        expireTime: formatTime(expireTime),
        currentTime: currentTimeStr,
        remainingTime: remainingTime
    };
}

// 倒计时函数
function countdown(seconds, callback) {
    console.log('⏰ 进入脚本倒计时:');
    function tick(remaining) {
        if (remaining > 0) {
            console.log(`   🕒 ${remaining}秒`);
            setTimeout(() => tick(remaining - 1), 1000);
        } else {
            console.log('   🚀 进入脚本...');
            setTimeout(callback, 500);
        }
    }
    tick(seconds);
}

